/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import page2020.view.Element;import page2020.view.Value;public class H5data extends Element<H5data, Value> {	public static final class Attr {		public static final String value = "value";	}	public H5data() {		super("data");	}	public H5data value(Object value) {		super.getAttrMap().put("value", value);		return this;	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.value:			return true;		default:			return super.isAttr(attrName);		}	}}